"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[5819],{628(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>d,default:()=>h,frontMatter:()=>c,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part1-enterprise-ai-delivery/architecture-reference-design","title":"Architecture Reference Design","description":"Here is a clean, realistic reference design featuring:","source":"@site/docs/part1-enterprise-ai-delivery/06-architecture-reference-design.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/06-architecture-reference-design","permalink":"/tutorials/part1-enterprise-ai-delivery/06-architecture-reference-design","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":6,"frontMatter":{"title":"Architecture Reference Design","slug":"/part1-enterprise-ai-delivery/06-architecture-reference-design","description":"Here is a clean, realistic reference design featuring:","sidebar_label":"6. Architecture reference design","pagination_label":"6. Architecture reference design","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"5. Seven days after kickoff","permalink":"/tutorials/part1-enterprise-ai-delivery/05-seven-days-after-kickoff"},"next":{"title":"7. HLD and service selection","permalink":"/tutorials/part1-enterprise-ai-delivery/07-hld-service-selection"}}');var a=n(4848),s=n(8453),r=n(8172);const o=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/06-architecture-reference-design.html","route":"/part1-enterprise-ai-delivery/06-architecture-reference-design","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"Architecture Reference Design","title":"Architecture Reference Design","description":"Here is a clean, realistic reference design featuring:","readingMinutes":3,"bodyClass":"","normalizeMath":false,"toc":[{"id":"0-components-in-the-setup","label":"0. Components in the setup"},{"id":"1-how-users-connect-to-the-react-frontend","label":"1. How users \u201cconnect\u201d to the React frontend"},{"id":"2-user-login-oidc-authorization-code-pkce","label":"2. User login (OIDC Authorization Code + PKCE)"},{"id":"3-react-calls-fastapi-authenticated","label":"3. React calls FastAPI (authenticated)"},{"id":"4-fastapi-validates-the-token-stateless-and-scalable","label":"4. FastAPI validates the token (stateless and scalable)"},{"id":"5-how-multi-tenancy-is-enforced-the-important-part","label":"5. How multi-tenancy is enforced (the important part)"},{"id":"6-defense-in-depth-database-level-isolation","label":"6. Defense-in-depth: database-level isolation"},{"id":"7-concurrency-multiple-users-at-the-same-time","label":"7. Concurrency: multiple users at the same time"},{"id":"8-where-to-store-tokens-important-practical-note","label":"8. Where to store tokens (important practical note)"},{"id":"summary-you-can-say-in-interviews","label":"Summary you can say in interviews"}],"html":"<div class=\\"container\\">\\n        \\n        <p>Here is a clean, realistic reference design featuring:</p>\\n        <ul>\\n            <li><strong>React frontend</strong> (hosted)</li>\\n            <li><strong>FastAPI backend</strong> running on GKE</li>\\n            <li><strong>Multi-tenancy</strong> (each user only sees their tenant\u2019s data)</li>\\n        </ul>\\n        <p>This describes the \u201cindustry standard\u201d flow using OIDC/OAuth2 + JWT.</p>\\n\\n        <h2 id=\\"0-components-in-the-setup\\">0. Components in the setup</h2>\\n        <div class=\\"component-grid\\">\\n            <div class=\\"component-card\\">\\n                <h4>Frontend</h4>\\n                <p>React app hosted on Cloud Storage + CDN or Cloud Run.</p>\\n            </div>\\n            <div class=\\"component-card\\">\\n                <h4>Identity Provider (IdP)</h4>\\n                <p>OIDC provider: Google Identity, Auth0, Okta, Entra ID, etc.</p>\\n            </div>\\n            <div class=\\"component-card\\">\\n                <h4>Backend</h4>\\n                <p>FastAPI pods on GKE exposed via Ingress.</p>\\n            </div>\\n            <div class=\\"component-card\\">\\n                <h4>Data</h4>\\n                <p>Postgres (shared DB) with <code>tenant_id</code> column.</p>\\n            </div>\\n        </div>\\n\\n        <h2 id=\\"1-how-users-connect-to-the-react-frontend\\">1. How users \u201cconnect\u201d to the React frontend</h2>\\n        <ol>\\n            <li>User types <code>https://app.example.com</code></li>\\n            <li>DNS \u2192 CDN / hosting</li>\\n            <li>Browser downloads static files: <code>index.html</code>, JS bundles, CSS</li>\\n            <li>React app boots in the browser</li>\\n        </ol>\\n        <p><em>At this point, the user is not authenticated yet \u2014 they\u2019ve only loaded a public website.</em></p>\\n\\n        <h2 id=\\"2-user-login-oidc-authorization-code-pkce\\">2. User login (OIDC Authorization Code + PKCE)</h2>\\n        <div class=\\"step-box\\">\\n            <p>When user clicks \u201cSign in\u201d:</p>\\n            <ol>\\n                <li>React redirects user to the IdP login page</li>\\n                <li>User logs in (password/SSO/MFA)</li>\\n                <li>IdP redirects back to your React app with an authorization code</li>\\n                <li>React exchanges the code for tokens:\\n                    <ul>\\n                        <li><strong>ID token</strong> (who the user is)</li>\\n                        <li><strong>Access token</strong> (JWT used to call your API)</li>\\n                        <li>Optional refresh token (to renew)</li>\\n                    </ul>\\n                </li>\\n            </ol>\\n        </div>\\n        <p><strong>Key point:</strong> the access token is what your backend uses to identify the user and their tenant.</p>\\n\\n        <h3 id=\\"where-is-the-tenant\\">Where is the tenant?</h3>\\n        <p>Two common patterns:</p>\\n        <ul>\\n            <li><code>tenant_id</code> is a claim inside the JWT (best for multi-tenant SaaS)</li>\\n            <li>or backend looks up <code>tenant_id</code> from <code>sub</code> (user id) in your DB</li>\\n        </ul>\\n        <p><em>In production, many do both: claim for speed + DB as source of truth.</em></p>\\n\\n        <h2 id=\\"3-react-calls-fastapi-authenticated\\">3. React calls FastAPI (authenticated)</h2>\\n        <p>React calls:</p>\\n        <pre>GET https://api.example.com/v1/chat</pre>\\n        <p>with header:</p>\\n        <pre>Authorization: Bearer &lt;access_token&gt;</pre>\\n        <p>Ingress routes to FastAPI service in GKE.</p>\\n\\n        <h2 id=\\"4-fastapi-validates-the-token-stateless-and-scalable\\">4. FastAPI validates the token (stateless and scalable)</h2>\\n        <p>Backend does JWT verification:</p>\\n        <ul>\\n            <li>Validate signature using the IdP\u2019s JWKS</li>\\n            <li>Validate: <code>iss</code> (issuer), <code>aud</code> (audience), <code>exp</code> (expiry)</li>\\n            <li>Extract claims: <code>sub</code> (user_id), <code>tenant_id</code> (or <code>org_id</code>), roles/groups</li>\\n        </ul>\\n        <p>This is fast and works with thousands of concurrent users because verification is stateless.</p>\\n\\n        <h3 id=\\"minimal-fastapi-pattern\\">Minimal FastAPI pattern</h3>\\n<pre>from fastapi import Depends, HTTPException\\nfrom fastapi.security import HTTPBearer, HTTPAuthorizationCredentials\\n\\nauth_scheme = HTTPBearer()\\n\\ndef verify_jwt(creds: HTTPAuthorizationCredentials = Depends(auth_scheme)):\\n    token = creds.credentials\\n    # 1) verify signature using JWKS\\n    # 2) validate iss/aud/exp\\n    # 3) return claims dict\\n    claims = {\\"sub\\": \\"user123\\", \\"tenant_id\\": \\"tenantA\\"}  # toy\\n    return claims\\n\\ndef tenant_context(claims=Depends(verify_jwt)):\\n    if \\"tenant_id\\" not in claims:\\n        raise HTTPException(status_code=403, detail=\\"No tenant\\")\\n    return {\\"user_id\\": claims[\\"sub\\"], \\"tenant_id\\": claims[\\"tenant_id\\"]}</pre>\\n        <p>Now every route can safely depend on <code>tenant_context</code>.</p>\\n\\n        <h2 id=\\"5-how-multi-tenancy-is-enforced-the-important-part\\">5. How multi-tenancy is enforced (the important part)</h2>\\n        <div class=\\"important-box\\">\\n            <strong>Industry standard rule:</strong> Every data access must be scoped by <code>tenant_id</code> (and often <code>user_id</code> too).\\n        </div>\\n\\n        <h3 id=\\"a-shared-database-toy-example\\">A) Shared database (toy example)</h3>\\n        <p>Your tables include <code>tenant_id</code>:</p>\\n        <ul>\\n            <li><code>documents(tenant_id, doc_id, text, ...)</code></li>\\n            <li><code>chunks(tenant_id, chunk_id, embedding_ref, ...)</code></li>\\n        </ul>\\n        <p>Query example:</p>\\n<pre class=\\"sql-code\\">SELECT doc_id, title, text, created_at\\nFROM documents\\nWHERE tenant_id = :tenant_id AND doc_id = :doc_id;</pre>\\n\\n        <h3 id=\\"b-vector-search-elastic-opensearch\\">B) Vector search (Elastic/OpenSearch)</h3>\\n        <p>Every retrieval query includes a filter:</p>\\n        <ul>\\n            <li><code>tenant_id = tenantA</code></li>\\n        </ul>\\n        <p>So even if embeddings are shared in one index, retrieval is tenant-scoped.</p>\\n\\n        <h2 id=\\"6-defense-in-depth-database-level-isolation\\">6. Defense-in-depth: database-level isolation</h2>\\n        <p>Even good teams eventually ship a bug. Industry standard is to add a backstop.</p>\\n        \\n        <h3 id=\\"postgres-row-level-security-rls\\">Postgres Row-Level Security (RLS)</h3>\\n        <ul>\\n            <li>Enable RLS on tables</li>\\n            <li>Policy: user can only see rows where <code>tenant_id = current_setting(\'app.tenant_id\')</code></li>\\n        </ul>\\n        <p>Then in FastAPI, set it per request (session):</p>\\n        <pre>SET app.tenant_id = \'tenantA\';</pre>\\n        <p>Now, even if a developer forgets a <code>WHERE tenant_id = ...</code>, Postgres blocks it.</p>\\n\\n        <h2 id=\\"7-concurrency-multiple-users-at-the-same-time\\">7. Concurrency: multiple users at the same time</h2>\\n        <p>This just works if you follow the above patterns because:</p>\\n        <ul>\\n            <li>React is client-side; users are isolated by browser sessions</li>\\n            <li>Backend is stateless; each request carries its token</li>\\n            <li>Tenant context is derived per request</li>\\n            <li>Data stores enforce tenant boundaries</li>\\n        </ul>\\n\\n        <h2 id=\\"8-where-to-store-tokens-important-practical-note\\">8. Where to store tokens (important practical note)</h2>\\n        <div class=\\"component-grid\\">\\n            <div class=\\"component-card\\">\\n                <h4>Option 1: Tokens in memory</h4>\\n                <p>SPA-friendly. Less risk of XSS token theft if you\u2019re careful. Needs refresh flow.</p>\\n            </div>\\n            <div class=\\"component-card\\">\\n                <h4>Option 2: httpOnly secure cookie</h4>\\n                <p>Backend sets cookie after login exchange (BFF pattern). Reduces token exposure in JS. Requires CSRF protections.</p>\\n            </div>\\n        </div>\\n\\n        <hr>\\n\\n        <h2 id=\\"summary-you-can-say-in-interviews\\">Summary you can say in interviews</h2>\\n        <div class=\\"interview-summary\\">\\n            \u201cUsers authenticate via OIDC. The React app obtains an access token (JWT) and calls the FastAPI API. The backend verifies the JWT and extracts tenant_id/user_id, then enforces multi-tenancy by scoping every DB and vector-search query to that tenant. For defense-in-depth we enable Postgres Row Level Security so cross-tenant access is blocked even if a query is missing filters. Because each request is stateless and carries identity, it scales naturally to many concurrent users.\u201d\\n        </div>\\n        \\n        <div class=\\"tr-note\\">\\n            <strong>Architecture extension</strong>\\n            The next vertical slice adds Elastic retrieval, prompt assembly,\\n            and the Azure OpenAI call. Apply the tenant and corpus filter\\n            inside retrieval, re-check authorization before fetching source\\n            documents, and preserve the same identity in citations and audit\\n            events so context cannot cross users.\\n        </div>\\n    </div>"}'),c={title:"Architecture Reference Design",slug:"/part1-enterprise-ai-delivery/06-architecture-reference-design",description:"Here is a clean, realistic reference design featuring:",sidebar_label:"6. Architecture reference design",pagination_label:"6. Architecture reference design",hide_title:!0,hide_table_of_contents:!0},d=void 0,l={},p=[];function u(e){return(0,a.jsx)(r.A,{content:o})}function h(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u()}}}]);